/**
 * The globe's surface (globe plan 2026-09-26-0539 §7, M0-M1): the WGS84
 * ellipsoid generated by 3d-tiles-renderer's `GeneratedSurfacePlugin`,
 * textured from the COMMITTED Blue Marble pyramid (EPSG:4326, levels 0-3,
 * served locally: no network), each tile drawn with a lit copy of one
 * template material so the sun makes a day and a night side.
 *
 * @see globe-surface.ts.md
 */

import * as THREE from "three";
import { TilesRenderer } from "3d-tiles-renderer";
import { XYZTilesOverlay } from "3d-tiles-renderer/plugins";

import { globeSource, type GlobeSourceId } from "./globe-sources.js";
import {
  GeneratedSurfacePlugin,
  type GeneratedSurfacePluginInstance,
} from "./vendor/generated-surface-plugin.js";

/** The surface's imagery, from the one registry (so it carries a credit). */
const IMAGERY = globeSource("blue-marble");

export const GLOBE_SURFACE = {
  /** The imagery's tiling: plate carrée, two tiles at level 0. */
  overlayProjection: IMAGERY.projection ?? "EPSG:4326",
  /** The committed levels (`scripts/fetch-globe-assets.mjs`). */
  levels: IMAGERY.levels ?? 1,
  /** The committed pyramid, served by the design system's routes. */
  imageryUrl: IMAGERY.path,
} as const;

export interface GlobeSurfaceOptions {
  readonly overlayProjection: string;
  readonly levels: number;
  readonly applyOverlayTexture: boolean;
}

export interface GlobeSurface {
  readonly tiles: TilesRenderer;
  readonly group: THREE.Object3D;
  readonly plugin: GeneratedSurfacePluginInstance;
  readonly overlay: XYZTilesOverlay;
  readonly options: GlobeSurfaceOptions;
  /** Per frame, before the render. */
  update(camera: THREE.Camera, renderer: THREE.WebGLRenderer): void;
  /** Loaded models and the library's tile load errors. */
  state(): { models: number; tileErrors: number };
  /** The registry sources on screen, for the credits line. */
  activeSources(): GlobeSourceId[];
  dispose(): void;
}

/** Every mesh under `root`, with its material typed. */
function tileMeshes(
  root: THREE.Object3D,
): THREE.Mesh<THREE.BufferGeometry, THREE.Material>[] {
  const out: THREE.Mesh<THREE.BufferGeometry, THREE.Material>[] = [];
  root.traverse((node) => {
    // instanceof narrows to Mesh<any, any>: name the types.
    if (node instanceof THREE.Mesh) {
      out.push(node as THREE.Mesh<THREE.BufferGeometry, THREE.Material>);
    }
  });
  return out;
}

/**
 * Swap each mesh's unlit tile material for a lit copy of `template` that
 * keeps the mesh's own texture, and record the copy in `owned`. The
 * renderer still holds (and later frees) the original material; the texture
 * belongs to the overlay, which releases it itself.
 */
export function useLitMaterial(
  model: THREE.Object3D,
  template: THREE.MeshStandardMaterial,
  owned: WeakSet<THREE.Material>,
): void {
  for (const mesh of tileMeshes(model)) {
    const unlit = mesh.material as THREE.MeshBasicMaterial;
    const lit = template.clone();
    lit.map = unlit.map ?? null;
    owned.add(lit);
    mesh.material = lit;
  }
}

/** Free the lit copies `useLitMaterial` made under `model`, not their maps. */
export function disposeLitMaterials(
  model: THREE.Object3D,
  owned: WeakSet<THREE.Material>,
): void {
  for (const mesh of tileMeshes(model)) {
    if (owned.has(mesh.material)) {
      owned.delete(mesh.material);
      mesh.material.dispose();
    }
  }
}

/**
 * The globe's surface. The caller adds `group` to its scene and calls
 * `update` every frame; `dispose` frees the tiles and the template.
 */
export function createGlobeSurface(): GlobeSurface {
  const options: GlobeSurfaceOptions = {
    overlayProjection: GLOBE_SURFACE.overlayProjection,
    levels: GLOBE_SURFACE.levels,
    applyOverlayTexture: true,
  };
  const overlay = new XYZTilesOverlay({
    url: GLOBE_SURFACE.imageryUrl,
    projection: options.overlayProjection,
    levels: options.levels,
  });
  const plugin = new GeneratedSurfacePlugin({
    overlay,
    applyOverlayTexture: options.applyOverlayTexture,
  });
  const tiles = new TilesRenderer();
  tiles.registerPlugin(plugin);
  const template = new THREE.MeshStandardMaterial({ roughness: 0.9 });
  const owned = new WeakSet<THREE.Material>();
  let models = 0;
  let tileErrors = 0;
  tiles.addEventListener("load-model", ({ scene }) => {
    models += 1;
    useLitMaterial(scene, template, owned);
  });
  tiles.addEventListener("dispose-model", ({ scene }) => {
    disposeLitMaterials(scene, owned);
  });
  tiles.addEventListener("load-error", () => {
    tileErrors += 1;
  });
  let cameraSet: THREE.Camera | null = null;
  return {
    tiles,
    group: tiles.group,
    plugin,
    overlay,
    options,
    update(camera, renderer) {
      if (cameraSet !== camera) {
        tiles.setCamera(camera);
        cameraSet = camera;
      }
      tiles.setResolutionFromRenderer(camera, renderer);
      camera.updateMatrixWorld();
      tiles.update();
    },
    state: () => ({ models, tileErrors }),
    activeSources: () => [IMAGERY.id],
    dispose() {
      tiles.dispose();
      template.dispose();
    },
  };
}
